Sub 'PrintFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'CARDAPCODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &carDapCodigo1.FromString(&GridStateDynamicFilter.Value) If not &carDapCodigo1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FiltercarDapCodigoDescription = format('%1 (%2)', "Código", "=") EndCase &carDapCodigo = &carDapCodigo1 print printBlockFiltercarDapCodigo EndIf Case &DynamicFiltersSelector1 = !'CARDAPDESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &carDapDescricao1.FromString(&GridStateDynamicFilter.Value) If not &carDapDescricao1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FiltercarDapDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FiltercarDapDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &carDapDescricao = &carDapDescricao1 print printBlockFiltercarDapDescricao EndIf Case &DynamicFiltersSelector1 = !'CARDAPMESANO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &carDapMesAno1.FromString(&GridStateDynamicFilter.Value) &carDapMesAno_To1.FromString(&GridStateDynamicFilter.ValueTo) If not &carDapMesAno1.IsEmpty() OR not &carDapMesAno_To1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FiltercarDapMesAnoDescription = format('%1 (%2)', "e Ano", "WWP_FilterRange") &carDapMesAno = &carDapMesAno1 print printBlockFiltercarDapMesAno &FiltercarDapMesAnoDescription = format('%1 (%2) %3', "e Ano", "WWP_FilterRange", "") &carDapMesAno = &carDapMesAno_To1 print printBlockFiltercarDapMesAno EndCase EndIf Case &DynamicFiltersSelector1 = !'CARDAPNUTRICIONISTA' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &carDapNutricionista1.FromString(&GridStateDynamicFilter.Value) If not &carDapNutricionista1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FiltercarDapNutricionistaDescription = format('%1 (%2)', "Nutricionista", "=") EndCase &carDapNutricionista = &carDapNutricionista1 print printBlockFiltercarDapNutricionista EndIf Case &DynamicFiltersSelector1 = !'CARDAPSTATUS' &carDapStatus1.FromString(&GridStateDynamicFilter.Value) If not &carDapStatus1.IsEmpty() &FiltercarDapStatus1ValueDescription = &carDapStatus1.EnumerationDescription()
&FiltercarDapStatusValueDescription = &FiltercarDapStatus1ValueDescription print printBlockFiltercarDapStatus EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'CARDAPCODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &carDapCodigo2.FromString(&GridStateDynamicFilter.Value) If not &carDapCodigo2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FiltercarDapCodigoDescription = format('%1 (%2)', "Código", "=") EndCase &carDapCodigo = &carDapCodigo2 print printBlockFiltercarDapCodigo EndIf Case &DynamicFiltersSelector2 = !'CARDAPDESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &carDapDescricao2.FromString(&GridStateDynamicFilter.Value) If not &carDapDescricao2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FiltercarDapDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FiltercarDapDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &carDapDescricao = &carDapDescricao2 print printBlockFiltercarDapDescricao EndIf Case &DynamicFiltersSelector2 = !'CARDAPMESANO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &carDapMesAno2.FromString(&GridStateDynamicFilter.Value) &carDapMesAno_To2.FromString(&GridStateDynamicFilter.ValueTo) If not &carDapMesAno2.IsEmpty() OR not &carDapMesAno_To2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FiltercarDapMesAnoDescription = format('%1 (%2)', "e Ano", "WWP_FilterRange") &carDapMesAno = &carDapMesAno2 print printBlockFiltercarDapMesAno &FiltercarDapMesAnoDescription = format('%1 (%2) %3', "e Ano", "WWP_FilterRange", "") &carDapMesAno = &carDapMesAno_To2 print printBlockFiltercarDapMesAno EndCase EndIf Case &DynamicFiltersSelector2 = !'CARDAPNUTRICIONISTA' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &carDapNutricionista2.FromString(&GridStateDynamicFilter.Value) If not &carDapNutricionista2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FiltercarDapNutricionistaDescription = format('%1 (%2)', "Nutricionista", "=") EndCase &carDapNutricionista = &carDapNutricionista2 print printBlockFiltercarDapNutricionista EndIf Case &DynamicFiltersSelector2 = !'CARDAPSTATUS' &carDapStatus2.FromString(&GridStateDynamicFilter.Value) If not &carDapStatus2.IsEmpty() &FiltercarDapStatus2ValueDescription = &carDapStatus2.EnumerationDescription()
&FiltercarDapStatusValueDescription = &FiltercarDapStatus2ValueDescription print printBlockFiltercarDapStatus EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'CARDAPCODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &carDapCodigo3.FromString(&GridStateDynamicFilter.Value) If not &carDapCodigo3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FiltercarDapCodigoDescription = format('%1 (%2)', "Código", "=") EndCase &carDapCodigo = &carDapCodigo3 print printBlockFiltercarDapCodigo EndIf Case &DynamicFiltersSelector3 = !'CARDAPDESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &carDapDescricao3.FromString(&GridStateDynamicFilter.Value) If not &carDapDescricao3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FiltercarDapDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FiltercarDapDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &carDapDescricao = &carDapDescricao3 print printBlockFiltercarDapDescricao EndIf Case &DynamicFiltersSelector3 = !'CARDAPMESANO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &carDapMesAno3.FromString(&GridStateDynamicFilter.Value) &carDapMesAno_To3.FromString(&GridStateDynamicFilter.ValueTo) If not &carDapMesAno3.IsEmpty() OR not &carDapMesAno_To3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FiltercarDapMesAnoDescription = format('%1 (%2)', "e Ano", "WWP_FilterRange") &carDapMesAno = &carDapMesAno3 print printBlockFiltercarDapMesAno &FiltercarDapMesAnoDescription = format('%1 (%2) %3', "e Ano", "WWP_FilterRange", "") &carDapMesAno = &carDapMesAno_To3 print printBlockFiltercarDapMesAno EndCase EndIf Case &DynamicFiltersSelector3 = !'CARDAPNUTRICIONISTA' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &carDapNutricionista3.FromString(&GridStateDynamicFilter.Value) If not &carDapNutricionista3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FiltercarDapNutricionistaDescription = format('%1 (%2)', "Nutricionista", "=") EndCase &carDapNutricionista = &carDapNutricionista3 print printBlockFiltercarDapNutricionista EndIf Case &DynamicFiltersSelector3 = !'CARDAPSTATUS' &carDapStatus3.FromString(&GridStateDynamicFilter.Value) If not &carDapStatus3.IsEmpty() &FiltercarDapStatus3ValueDescription = &carDapStatus3.EnumerationDescription()
&FiltercarDapStatusValueDescription = &FiltercarDapStatus3ValueDescription print printBlockFiltercarDapStatus EndIf EndCase EndIf EndIf EndIf If not (&TFcarDapCodigo.IsEmpty() AND &TFcarDapCodigo_To.IsEmpty()) print printBlockTFcarDapCodigo &TFcarDapCodigo_To_Description = format('%1 (%2)', "Código", "WWP_TSTo") print printBlockTFcarDapCodigo_To EndIf If not &TFcarDapDescricao_Sel.IsEmpty() print printBlockTFcarDapDescricao_Sel Else If not &TFcarDapDescricao.IsEmpty() print printBlockTFcarDapDescricao EndIf EndIf If not &TFcarDapNutricionista_Sel.IsEmpty() print printBlockTFcarDapNutricionista_Sel Else If not &TFcarDapNutricionista.IsEmpty() print printBlockTFcarDapNutricionista EndIf EndIf If not (&TFcarDapMesAno.IsEmpty() AND &TFcarDapMesAno_To.IsEmpty()) print printBlockTFcarDapMesAno &TFcarDapMesAno_To_Description = format('%1 (%2)', "Mês e Ano", "WWP_TSTo") print printBlockTFcarDapMesAno_To EndIf &TFcarDapStatus_Sels.FromJson(&TFcarDapStatus_SelsJson) If not &TFcarDapStatus_Sels.Count = 0 &i = 1 For &TFcarDapStatus_Sel in &TFcarDapStatus_Sels If &i = 1 &TFcarDapStatus_SelDscs = '' Else &TFcarDapStatus_SelDscs += ', ' EndIf &FilterTFcarDapStatus_SelValueDescription = &TFcarDapStatus_Sel.EnumerationDescription()
&TFcarDapStatus_SelDscs += &FilterTFcarDapStatus_SelValueDescription &i += 1 EndFor print printBlockTFcarDapStatus_Sel EndIf &TFcarDapLiberarAcesso_Sels.FromJson(&TFcarDapLiberarAcesso_SelsJson) If not &TFcarDapLiberarAcesso_Sels.Count = 0 &i = 1 For &TFcarDapLiberarAcesso_Sel in &TFcarDapLiberarAcesso_Sels If &i = 1 &TFcarDapLiberarAcesso_SelDscs = '' Else &TFcarDapLiberarAcesso_SelDscs += ', ' EndIf &FilterTFcarDapLiberarAcesso_SelValueDescription = '' Do Case Case &TFcarDapLiberarAcesso_Sel.ToString().Trim() = !"N" &FilterTFcarDapLiberarAcesso_SelValueDescription = "Não"
Case &TFcarDapLiberarAcesso_Sel.ToString().Trim() = !"A" &FilterTFcarDapLiberarAcesso_SelValueDescription = "Liberar Pelo Atendimento"
Case &TFcarDapLiberarAcesso_Sel.ToString().Trim() = !"L" &FilterTFcarDapLiberarAcesso_SelValueDescription = "Liberar"
EndCase
&TFcarDapLiberarAcesso_SelDscs += &FilterTFcarDapLiberarAcesso_SelValueDescription &i += 1 EndFor print printBlockTFcarDapLiberarAcesso_Sel EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
print printBlockBeforeGrid print printBlockLines_titles
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnscardapio order carDapCodigo when &OrderedBy = 1 AND &OrderedDsc = False order (carDapCodigo) when &OrderedBy = 1 AND &OrderedDsc = True order carDapDescricao when &OrderedBy = 2 AND &OrderedDsc = False order (carDapDescricao) when &OrderedBy = 2 AND &OrderedDsc = True order carDapNutricionista when &OrderedBy = 3 AND &OrderedDsc = False order (carDapNutricionista) when &OrderedBy = 3 AND &OrderedDsc = True order carDapMesAno when &OrderedBy = 4 AND &OrderedDsc = False order (carDapMesAno) when &OrderedBy = 4 AND &OrderedDsc = True order carDapStatus when &OrderedBy = 5 AND &OrderedDsc = False order (carDapStatus) when &OrderedBy = 5 AND &OrderedDsc = True order carDapLiberarAcesso when &OrderedBy = 6 AND &OrderedDsc = False order (carDapLiberarAcesso) when &OrderedBy = 6 AND &OrderedDsc = True
using trnscardapioWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &carDapCodigo1, &carDapDescricao1, &carDapMesAno1, &carDapMesAno_To1 , &carDapNutricionista1, &carDapStatus1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2, &carDapCodigo2 , &carDapDescricao2, &carDapMesAno2, &carDapMesAno_To2, &carDapNutricionista2, &carDapStatus2, &DynamicFiltersEnabled3 , &DynamicFiltersSelector3, &DynamicFiltersOperator3, &carDapCodigo3, &carDapDescricao3, &carDapMesAno3, &carDapMesAno_To3 , &carDapNutricionista3, &carDapStatus3, &TFcarDapCodigo, &TFcarDapCodigo_To, &TFcarDapDescricao, &TFcarDapDescricao_Sel , &TFcarDapNutricionista, &TFcarDapNutricionista_Sel, &TFcarDapMesAno, &TFcarDapMesAno_To, &TFcarDapStatus_Sels, &TFcarDapLiberarAcesso_Sels) Where prefCodigo = &prefCodigo &carDapStatusDescription = carDapStatus.EnumerationDescription() &carDapLiberarAcessoDescription = '' Do Case Case carDapLiberarAcesso.ToString().Trim() = !"N" &carDapLiberarAcessoDescription = "Não"
Case carDapLiberarAcesso.ToString().Trim() = !"A" &carDapLiberarAcessoDescription = "Liberar Pelo Atendimento"
Case carDapLiberarAcesso.ToString().Trim() = !"L" &carDapLiberarAcessoDescription = "Liberar"
EndCase
Do 'BeforePrintLine' print printBlockLines_data Do 'AfterPrintLine' EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnscardapioWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnscardapioWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnscardapioWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFCARDAPCODIGO" &TFcarDapCodigo.FromString(&GridStateFilterValue.Value) &TFcarDapCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFCARDAPDESCRICAO" &TFcarDapDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFCARDAPDESCRICAO_SEL" &TFcarDapDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFCARDAPNUTRICIONISTA" &TFcarDapNutricionista.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFCARDAPNUTRICIONISTA_SEL" &TFcarDapNutricionista_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFCARDAPMESANO" &TFcarDapMesAno.FromString(&GridStateFilterValue.Value) &TFcarDapMesAno_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFCARDAPSTATUS_SEL" &TFcarDapStatus_SelsJson = &GridStateFilterValue.Value &TFcarDapStatus_Sels.FromJson(&TFcarDapStatus_SelsJson) Case &GridStateFilterValue.Name = !"TFCARDAPLIBERARACESSO_SEL" &TFcarDapLiberarAcesso_SelsJson = &GridStateFilterValue.Value &TFcarDapLiberarAcesso_Sels.FromJson(&TFcarDapLiberarAcesso_SelsJson) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
